def serve(args) -> int:
    """Run the server until SIGINT/SIGTERM/SIGBREAK; return the process exit code."""
    try:
        server = make_server(
            args.db, args.admin_key, args.port, args.rate_limit, args.fake_clock)
    except (sqlite3.Error, OSError) as exc:
        print("linkvault: cannot start server: %s" % exc, file=sys.stderr)
